WITH base AS (SELECT *, DATE_TRUNC('WEEK', last_restock) AS last_restock_period, DATE_ADD(last_restock, 88) AS last_restock_plus_88d FROM inventory WHERE store_id IN (1, 2, 4, 5)), enriched AS (SELECT id, store_id, product_id, quantity, last_restock, last_restock_plus_88d, AVG(quantity) OVER (PARTITION BY product_id ORDER BY last_restock_plus_88d, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_quantity, MIN(quantity) OVER (PARTITION BY product_id ORDER BY last_restock_plus_88d, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_quantity, MAX(quantity) OVER (PARTITION BY product_id ORDER BY last_restock_plus_88d, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_quantity, SUM(quantity) OVER (PARTITION BY product_id ORDER BY last_restock_plus_88d, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_quantity FROM base), base_inventory AS (SELECT *, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock, CASE WHEN quantity >= 259 THEN 'High' WHEN quantity >= 90 THEN 'Medium' ELSE 'Low' END AS quantity_band FROM enriched WHERE last_restock > DATE '2023-02-18'), metrics AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY product_id, store_id ORDER BY last4_avg_quantity NULLS FIRST) AS last4_avg_quantity_percent_rank, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last4_avg_quantity, id) AS row_seq, SUM(last4_max_quantity) OVER (PARTITION BY store_id ORDER BY last_restock_plus_88d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_last4_max_quantity FROM base_inventory), enriched_inventory AS (SELECT e.*, d.product_name FROM metrics e LEFT JOIN products d ON e.product_id = d.id), filtered AS (SELECT id, store_id, product_id, quantity, last_restock_plus_88d, last4_avg_quantity, last4_min_quantity, last4_max_quantity, last4_sum_quantity, row_seq, running_last4_max_quantity, product_name, CAST(quantity AS DOUBLE) AS quantity_str FROM enriched_inventory WHERE product_id IN (3, 4, 8, 10)) SELECT CASE WHEN quantity >= 250 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, BIT_OR(quantity) AS quantity_bit_or, ROUND(AVG(last4_sum_quantity), 2) AS avg_last4_sum_quantity FROM filtered GROUP BY 1 HAVING quantity_bit_or < 1000 ORDER BY quantity_tier DESC NULLS LAST
